insert into public.products (id, name, slug, description, price, compare_at_price, category_id, images, stock, rating, review_count, is_trending, is_active, created_at) values
  ('22222222-0000-4000-8000-000000000001', 'Ухаалаг цаг Series 9', 'smart-watch-series-9', 'Үргэлж асаалттай Retina дэлгэц, зүрхний цохилт болон нойрны хяналттай. Хөнгөн цагаан их биетэй, батарей нь 18 цаг хүртэл ажиллана.', 159.99, 199.99, '11111111-0000-4000-8000-000000000002', array['https://images.unsplash.com/photo-1579586337278-3befd40fd17a?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1546868871-7041f2a55e12?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?w=1000&q=80&auto=format&fit=crop']::text[], 42, 4.5, 128, true, true, now() - interval '0 days'),
  ('22222222-0000-4000-8000-000000000002', 'Аяллын үүргэвч', 'travel-backpack', 'Ус нэвтрүүлдэггүй даавуу, 15 инчийн зөөврийн компьютерийн жийргэвчтэй тасалгаа, арьсан оосортой. Амралтын аялал болон өдөр тутмын хэрэглээнд тохиромжтой.', 49.99, 58.99, '11111111-0000-4000-8000-000000000004', array['https://images.unsplash.com/photo-1491637639811-60e2756cc1c7?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1547949003-9792a18a2601?w=1000&q=80&auto=format&fit=crop']::text[], 65, 4.4, 96, true, true, now() - interval '2 days'),
  ('22222222-0000-4000-8000-000000000003', 'Утасгүй чихэвч', 'wireless-earbuds', 'Тунгалаг дуугаралт, идэвхтэй дуу чимээ бууруулагчтай. Халаасны цэнэглэгч хайрцагтайгаа нийт 24 цаг ажиллана.', 29.99, null, '11111111-0000-4000-8000-000000000002', array['https://images.unsplash.com/photo-1572569511254-d8f925fe2cbb?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1600294037681-c80b4cb5b434?w=1000&q=80&auto=format&fit=crop']::text[], 120, 4.6, 243, true, true, now() - interval '4 days'),
  ('22222222-0000-4000-8000-000000000004', 'Эрэгтэй үнэртэй ус', 'perfume-for-men', 'Бергамот, хуш мод, хувын үнэр бүхий модлог үнэртэй ус. Удаан тогтдог, 100 мл.', 69.99, 89.99, '11111111-0000-4000-8000-000000000005', array['https://images.unsplash.com/photo-1622618991746-fe6004db3a47?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1587017539504-67cfbddac569?w=1000&q=80&auto=format&fit=crop']::text[], 30, 4.3, 75, true, true, now() - interval '6 days'),
  ('22222222-0000-4000-8000-000000000005', 'Moon Glow чийдэн', 'moon-glow-lamp', 'Гэрлийг нь тохируулж болдог дулаан туяа, маалинган бүрхүүл, гурван хөлтэй модон суурьтай. Орны хажуугийн ширээнд яг тохирно.', 24.99, null, '11111111-0000-4000-8000-000000000003', array['https://images.unsplash.com/photo-1517991104123-1d56a6e81ed9?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1565814329452-e1efa11c5b89?w=1000&q=80&auto=format&fit=crop']::text[], 8, 4.4, 58, true, true, now() - interval '8 days'),
  ('22222222-0000-4000-8000-000000000006', 'Сонгодог авиатор нарны шил', 'classic-aviator-sunglasses', 'UV400 хамгаалалттай поляризацтай шил, хөнгөн металл хүрээтэй. Хатуу гэр, арчих алчууртай.', 39.99, 49.99, '11111111-0000-4000-8000-000000000001', array['https://images.unsplash.com/photo-1572635196237-14b3f281503f?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1577803645773-f96470509666?w=1000&q=80&auto=format&fit=crop']::text[], 54, 4.5, 88, true, true, now() - interval '10 days'),
  ('22222222-0000-4000-8000-000000000007', 'Ретро дугуй нарны шил', 'round-retro-sunglasses', 'Винтеж загварын дугуй хүрээ, градиент шилтэй. Хэт ягаан туяанаас бүрэн хамгаална.', 34.99, null, '11111111-0000-4000-8000-000000000001', array['https://images.unsplash.com/photo-1511499767150-a48a237f0083?w=1000&q=80&auto=format&fit=crop']::text[], 40, 4.2, 41, false, true, now() - interval '12 days'),
  ('22222222-0000-4000-8000-000000000008', 'Арьсан түрийвч', 'leather-bifold-wallet', 'Жинхэнэ арьсан, RFID хамгаалалттай, зургаан картын тасалгаатай нимгэн түрийвч.', 29.99, null, '11111111-0000-4000-8000-000000000001', array['https://images.unsplash.com/photo-1627123424574-724758594e93?w=1000&q=80&auto=format&fit=crop']::text[], 75, 4.7, 132, false, true, now() - interval '14 days'),
  ('22222222-0000-4000-8000-000000000009', 'Жинхэнэ арьсан бүс', 'genuine-leather-belt', 'Гараар боловсруулсан үхрийн арьсан бүс, өнгөлсөн металл горхитой. Олон хэмжээтэй.', 24.99, null, '11111111-0000-4000-8000-000000000001', array['https://images.unsplash.com/photo-1624222247344-550fb60583dc?w=1000&q=80&auto=format&fit=crop']::text[], 60, 4.3, 37, false, true, now() - interval '16 days'),
  ('22222222-0000-4000-8000-000000000010', 'Өдөр тутмын бейсболк малгай', 'everyday-baseball-cap', 'Агаар нэвтрүүлдэг хөвөн даавуун малгай, тохируулгатай оосор, муруй саравчтай.', 19.99, null, '11111111-0000-4000-8000-000000000001', array['https://images.unsplash.com/photo-1588850561407-ed78c282e89b?w=1000&q=80&auto=format&fit=crop']::text[], 90, 4.1, 29, false, true, now() - interval '18 days'),
  ('22222222-0000-4000-8000-000000000011', 'Минимал гар цаг', 'minimal-analog-watch', 'Цэвэрхэн нүүр, сапфир бүрээстэй шил, сольж болох силикон оосортой. 50 м хүртэл ус нэвтрүүлэхгүй.', 89.99, 109.99, '11111111-0000-4000-8000-000000000001', array['https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1524592094714-0f0654e20314?w=1000&q=80&auto=format&fit=crop']::text[], 22, 4.6, 64, false, true, now() - interval '20 days'),
  ('22222222-0000-4000-8000-000000000012', 'Ягаан алтлаг хронограф цаг', 'rose-gold-chronograph', 'Ягаан алтан өнгөлгөөтэй зэвэрдэггүй ган хронограф, торон бугуйвчтай.', 129.99, null, '11111111-0000-4000-8000-000000000001', array['https://images.unsplash.com/photo-1522312346375-d1a52e2b99b3?w=1000&q=80&auto=format&fit=crop']::text[], 14, 4.8, 51, false, true, now() - interval '22 days'),
  ('22222222-0000-4000-8000-000000000013', 'Студи чихэвч', 'studio-over-ear-headphones', 'Гүн басс, зөөлөн жийргэвчтэй, утасгүйгээр 40 цаг сонсох боломжтой.', 79.99, 99.99, '11111111-0000-4000-8000-000000000002', array['https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1583394838336-acd977736f90?w=1000&q=80&auto=format&fit=crop']::text[], 35, 4.6, 187, true, true, now() - interval '24 days'),
  ('22222222-0000-4000-8000-000000000014', 'Зөөврийн Bluetooth чанга яригч', 'portable-bluetooth-speaker', '360° дуугаралт, IPX7 усны хамгаалалттай, бат бөх даавуун их биетэй. 12 цаг тасралтгүй ажиллана.', 49.99, null, '11111111-0000-4000-8000-000000000002', array['https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=1000&q=80&auto=format&fit=crop']::text[], 48, 4.4, 102, false, true, now() - interval '26 days'),
  ('22222222-0000-4000-8000-000000000015', 'Шууд хэвлэдэг камер', 'instant-film-camera', 'Чиглүүл, дар, хэвлэ. Автомат гэрэлтүүлэг, суурилуулсан флэш, селфи толинцортой.', 69.99, null, '11111111-0000-4000-8000-000000000002', array['https://images.unsplash.com/photo-1526170375885-4d8ecf77b99f?w=1000&q=80&auto=format&fit=crop']::text[], 18, 4.5, 73, false, true, now() - interval '28 days'),
  ('22222222-0000-4000-8000-000000000016', 'Нимгэн утасгүй keyboard', 'slim-wireless-keyboard', 'Намхан товчлууртай, хэд хэдэн төхөөрөмжтэй зэрэг холбогдох боломжтой, цэнэглэдэг батарейтай.', 45.99, null, '11111111-0000-4000-8000-000000000002', array['https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=1000&q=80&auto=format&fit=crop']::text[], 52, 4.3, 58, false, true, now() - interval '30 days'),
  ('22222222-0000-4000-8000-000000000017', 'Эргономик утасгүй хулгана', 'ergonomic-wireless-mouse', 'Чимээгүй даралт, тохируулгатай DPI, өдөржин ашиглахад тав тухтай хэлбэртэй.', 19.99, null, '11111111-0000-4000-8000-000000000002', array['https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=1000&q=80&auto=format&fit=crop']::text[], 110, 4.2, 91, false, true, now() - interval '32 days'),
  ('22222222-0000-4000-8000-000000000018', 'Pro таблет 11"', 'pro-tablet-11', '11 инчийн Liquid дэлгэц, өдөржин ажиллах батарейтай. Үзэг болон keyboard дэмжинэ.', 399.99, 449.99, '11111111-0000-4000-8000-000000000002', array['https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=1000&q=80&auto=format&fit=crop']::text[], 12, 4.7, 46, false, true, now() - interval '34 days'),
  ('22222222-0000-4000-8000-000000000019', 'Утасгүй тоглоомын жойстик', 'wireless-game-controller', 'Мэдрэмтгий гох товч, чичиргээт хариу үйлдэл, цэнэглэдэг батарейтай.', 54.99, null, '11111111-0000-4000-8000-000000000002', array['https://images.unsplash.com/photo-1592840496694-26d035b52b48?w=1000&q=80&auto=format&fit=crop']::text[], 33, 4.6, 120, false, true, now() - interval '36 days'),
  ('22222222-0000-4000-8000-000000000020', 'USB-C хурдан цэнэглэгч', 'usb-c-fast-charger', '65 Вт GaN цэнэглэгч, 2 м сүлжмэл кабельтай. Зөөврийн компьютер, таблет, утас цэнэглэнэ.', 24.99, null, '11111111-0000-4000-8000-000000000002', array['https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=1000&q=80&auto=format&fit=crop']::text[], 6, 4.4, 67, false, true, now() - interval '38 days'),
  ('22222222-0000-4000-8000-000000000021', 'Шаазан вааранд суккулент', 'succulent-in-ceramic-pot', 'Гаа ногоон өнгийн шаазан вааранд суулгасан, арчилгаа бага шаарддаг суккулент. Ширээг тань амьд болгоно.', 18.99, null, '11111111-0000-4000-8000-000000000003', array['https://images.unsplash.com/photo-1485955900006-10f4d324d411?w=1000&q=80&auto=format&fit=crop']::text[], 45, 4.7, 80, false, true, now() - interval '40 days'),
  ('22222222-0000-4000-8000-000000000022', 'Минимал шаазан аяга', 'minimal-ceramic-mug', 'Сатин паалантай шаазан аяга. Аяга угаагч, богино долгионы зууханд хэрэглэж болно, 350 мл.', 12.99, null, '11111111-0000-4000-8000-000000000003', array['https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?w=1000&q=80&auto=format&fit=crop']::text[], 140, 4.5, 54, false, true, now() - interval '42 days'),
  ('22222222-0000-4000-8000-000000000023', 'Унжлагат таазны гэрэл', 'pendant-ceiling-light', 'Скандинав загварын бөмбөгөр гэрэл, будсан ган их бие, уртыг нь тохируулдаг утастай.', 59.99, null, '11111111-0000-4000-8000-000000000003', array['https://images.unsplash.com/photo-1543198126-a8ad8e47fb22?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1540932239986-30128078f3c5?w=1000&q=80&auto=format&fit=crop']::text[], 20, 4.4, 23, false, true, now() - interval '44 days'),
  ('22222222-0000-4000-8000-000000000024', 'Тохируулгат ширээний чийдэн', 'adjustable-desk-lamp', 'Нугалдаг гар, хүнд суурь, ажилд төвлөрөхөд зориулсан дулаан LED гэрэлтэй.', 39.99, null, '11111111-0000-4000-8000-000000000003', array['https://images.unsplash.com/photo-1507473885765-e6ed057f782c?w=1000&q=80&auto=format&fit=crop']::text[], 28, 4.3, 36, false, true, now() - interval '46 days'),
  ('22222222-0000-4000-8000-000000000025', 'Товчин хээтэй сандал', 'tufted-accent-chair', 'Товчоор чимсэн зөөлөн бүрээс, хатуу модон хөлтэй. Өрөөний аль ч буланг онцолно.', 189.99, 229.99, '11111111-0000-4000-8000-000000000003', array['https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?w=1000&q=80&auto=format&fit=crop']::text[], 7, 4.6, 19, false, true, now() - interval '48 days'),
  ('22222222-0000-4000-8000-000000000026', 'Зөөлөн хөвөн дэр', 'soft-cotton-pillow', 'Харшил үүсгэдэггүй дүүргэгчтэй, агаар нэвтрүүлдэг 300 утасны нягттай хөвөн бүрээстэй.', 22.99, null, '11111111-0000-4000-8000-000000000003', array['https://images.unsplash.com/photo-1584100936595-c0654b55a2e2?w=1000&q=80&auto=format&fit=crop']::text[], 70, 4.4, 47, false, true, now() - interval '50 days'),
  ('22222222-0000-4000-8000-000000000027', 'Жижиг кактус', 'mini-cactus-pot', 'Терракота вааранд суулгасан жижигхэн кактус. Арчлахад хамгийн амар ургамал.', 9.99, null, '11111111-0000-4000-8000-000000000003', array['https://images.unsplash.com/photo-1459411552884-841db9b3cc2a?w=1000&q=80&auto=format&fit=crop']::text[], 95, 4.8, 61, false, true, now() - interval '52 days'),
  ('22222222-0000-4000-8000-000000000028', 'Энгийн цагаан футболк', 'essential-white-t-shirt', 'Органик хөвөн даавуун зузаан футболк, сул загвартай, бэхжүүлсэн захтай.', 19.99, null, '11111111-0000-4000-8000-000000000004', array['https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=1000&q=80&auto=format&fit=crop']::text[], 200, 4.5, 210, false, true, now() - interval '54 days'),
  ('22222222-0000-4000-8000-000000000029', 'Арьсан байкер куртик', 'leather-biker-jacket', 'Зөөлөн хурганы арьсан, ташуу цахилгаантай, мөрөндөө оёмол хээтэй.', 149.99, 189.99, '11111111-0000-4000-8000-000000000004', array['https://images.unsplash.com/photo-1551028719-00167b16eac5?w=1000&q=80&auto=format&fit=crop']::text[], 15, 4.7, 44, true, true, now() - interval '56 days'),
  ('22222222-0000-4000-8000-000000000030', 'Сонгодог саарал hoodie', 'classic-grey-hoodie', 'Дотор талдаа зөөлөн флистэй, урд халаастай, доторлогоотой малгайтай.', 44.99, null, '11111111-0000-4000-8000-000000000004', array['https://images.unsplash.com/photo-1556821840-3a63f95609a7?w=1000&q=80&auto=format&fit=crop']::text[], 80, 4.6, 98, false, true, now() - interval '58 days'),
  ('22222222-0000-4000-8000-000000000031', 'Нарийн жинсэн өмд', 'slim-fit-denim-jeans', 'Сунадаг жинсэн даавуу, орчин үеийн нарийн загвар, дунд бүсэлхийтэй.', 59.99, null, '11111111-0000-4000-8000-000000000004', array['https://images.unsplash.com/photo-1542272604-787c3835535d?w=1000&q=80&auto=format&fit=crop']::text[], 64, 4.3, 77, false, true, now() - interval '60 days'),
  ('22222222-0000-4000-8000-000000000032', 'Urban Runner пүүз', 'urban-runner-sneakers', 'Хөнгөн сүлжмэл дээд хэсэг, хотоор алхахад зориулсан зөөлөн ултай.', 79.99, 94.99, '11111111-0000-4000-8000-000000000004', array['https://images.unsplash.com/photo-1560769629-975ec94e6a86?w=1000&q=80&auto=format&fit=crop']::text[], 38, 4.5, 112, false, true, now() - interval '62 days'),
  ('22222222-0000-4000-8000-000000000033', 'Арьсан мессенжер үүргэвч', 'leather-messenger-backpack', 'Лаа шингээсэн даавуу ба арьсаар хийсэн, горхин бэхэлгээтэй, жийргэвчтэй компьютерийн халаастай.', 89.99, null, '11111111-0000-4000-8000-000000000004', array['https://images.unsplash.com/photo-1622560480605-d83c853bc5c3?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1585916420730-d7f95e942d43?w=1000&q=80&auto=format&fit=crop']::text[], 21, 4.6, 39, false, true, now() - interval '64 days'),
  ('22222222-0000-4000-8000-000000000034', 'Цэцгийн үнэртэй ус', 'floral-eau-de-parfum', 'Сарнай, цээнэ цэцэг, цагаан заарын зөөлөн цэцгэн үнэр. 50 мл.', 74.99, null, '11111111-0000-4000-8000-000000000005', array['https://images.unsplash.com/photo-1595425970377-c9703cf48b6d?w=1000&q=80&auto=format&fit=crop']::text[], 26, 4.6, 82, false, true, now() - interval '66 days'),
  ('22222222-0000-4000-8000-000000000035', 'Чийгшүүлэх арьс арчилгааны багц', 'hydrating-skincare-set', 'Гиалуроны хүчилтэй цэвэрлэгч, тоник, тос — өдөр бүрийн чийгшүүлэлтэд.', 34.99, null, '11111111-0000-4000-8000-000000000005', array['https://images.unsplash.com/photo-1611930022073-b7a4ba5fcccd?w=1000&q=80&auto=format&fit=crop']::text[], 44, 4.5, 66, false, true, now() - interval '68 days'),
  ('22222222-0000-4000-8000-000000000036', 'Ургамлын серумын багц', 'botanical-serum-collection', 'Гэрэлтүүлэх, чангалах, тайвшруулах үйлчилгээтэй ургамлын гаралтай гурван серум.', 42.99, null, '11111111-0000-4000-8000-000000000005', array['https://images.unsplash.com/photo-1612817288484-6f916006741a?w=1000&q=80&auto=format&fit=crop']::text[], 31, 4.4, 38, false, true, now() - interval '70 days'),
  ('22222222-0000-4000-8000-000000000037', 'Мэргэжлийн будгийн бийрний багц', 'pro-makeup-brush-set', 'Хэт зөөлөн нийлэг үстэй, амьтны гаралгүй 12 бийр, аяллын уутны хамт.', 27.99, null, '11111111-0000-4000-8000-000000000005', array['https://images.unsplash.com/photo-1596462502278-27bfdc403348?w=1000&q=80&auto=format&fit=crop']::text[], 58, 4.7, 105, false, true, now() - interval '72 days'),
  ('22222222-0000-4000-8000-000000000038', 'Зөөлөн нүүрний тос', 'gentle-face-cream', 'Мэдрэг арьсанд зориулсан үнэргүй, өдөр тутмын чийгшүүлэгч тос. 75 мл.', 16.99, null, '11111111-0000-4000-8000-000000000005', array['https://images.unsplash.com/photo-1620916566398-39f1143ab7be?w=1000&q=80&auto=format&fit=crop']::text[], 4, 4.3, 27, false, true, now() - interval '74 days'),
  ('22222222-0000-4000-8000-000000000039', 'Зургаан талт гантелийн багц', 'hex-dumbbell-set', 'Резинэн бүрээстэй зургаан талт гантель, гулгадаггүй хром бариултай. 2 × 10 кг.', 64.99, null, '11111111-0000-4000-8000-000000000006', array['https://images.unsplash.com/photo-1638536532686-d610adfc8e5c?w=1000&q=80&auto=format&fit=crop']::text[], 19, 4.7, 71, false, true, now() - interval '76 days'),
  ('22222222-0000-4000-8000-000000000040', 'Резинэн дасгалын багц', 'resistance-training-kit', 'Таван резинэн тууз, хаалганы бэхэлгээ, бариул, шагайны оосортой.', 29.99, null, '11111111-0000-4000-8000-000000000006', array['https://images.unsplash.com/photo-1584735935682-2f2b69dff9d2?w=1000&q=80&auto=format&fit=crop']::text[], 50, 4.4, 49, false, true, now() - interval '78 days'),
  ('22222222-0000-4000-8000-000000000041', 'Премиум йогийн дэвсгэр', 'premium-yoga-mat', '6 мм зузаан, гулгадаггүй, байрлалын зураастай, зөөх оосортой дэвсгэр.', 32.99, null, '11111111-0000-4000-8000-000000000006', array['https://images.unsplash.com/photo-1601925260368-ae2f83cf8b7f?w=1000&q=80&auto=format&fit=crop']::text[], 62, 4.6, 93, false, true, now() - interval '80 days'),
  ('22222222-0000-4000-8000-000000000042', 'Сагсан бөмбөг', 'indoor-outdoor-basketball', 'Гадаа, дотор тоглоход тохиромжтой. Нийлмэл арьсан бүрээс, сайн атгалт өгөх гүн ховилтой. 7-р хэмжээ.', 29.99, null, '11111111-0000-4000-8000-000000000006', array['https://images.unsplash.com/photo-1519861531473-9200262188bf?w=1000&q=80&auto=format&fit=crop']::text[], 40, 4.5, 58, false, true, now() - interval '82 days'),
  ('22222222-0000-4000-8000-000000000043', 'Хөл бөмбөг', 'match-football', 'Дулаанаар наасан хэсгүүд нь нислэгийг жигд, мэдрэмжийг тогтвортой болгоно. 5-р хэмжээ.', 24.99, null, '11111111-0000-4000-8000-000000000006', array['https://images.unsplash.com/photo-1614632537190-23e4146777db?w=1000&q=80&auto=format&fit=crop']::text[], 46, 4.4, 34, false, true, now() - interval '84 days'),
  ('22222222-0000-4000-8000-000000000044', 'Термос усны сав', 'insulated-water-bottle', 'Давхар ханатай зэвэрдэггүй ган сав ундааг 24 цаг хүйтэн, 12 цаг халуун байлгана. 750 мл.', 21.99, null, '11111111-0000-4000-8000-000000000006', array['https://images.unsplash.com/photo-1602143407151-7111542de6e8?w=1000&q=80&auto=format&fit=crop']::text[], 130, 4.7, 156, false, true, now() - interval '86 days'),
  ('22222222-0000-4000-8000-000000000045', 'Гүйлтийн пүүз', 'performance-running-shoes', 'Уян зөөлөн ул, агаар нэвтрүүлдэг торон дээд хэсэгтэй — урт зайн гүйлтэд зориулав.', 89.99, 119.99, '11111111-0000-4000-8000-000000000006', array['https://images.unsplash.com/photo-1491553895911-0055eca6402d?w=1000&q=80&auto=format&fit=crop']::text[], 27, 4.6, 84, false, true, now() - interval '88 days'),
  ('22222222-0000-4000-8000-000000000046', 'Тедди баавгай', 'classic-teddy-bear', 'Хатгамал нүүртэй, хэт зөөлөн тоглоом баавгай. Бүх насныханд аюулгүй.', 19.99, null, '11111111-0000-4000-8000-000000000007', array['https://images.unsplash.com/photo-1530325553241-4f6e7690cf36?w=1000&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1559454403-b8fb88521f11?w=1000&q=80&auto=format&fit=crop']::text[], 55, 4.9, 142, false, true, now() - interval '90 days'),
  ('22222222-0000-4000-8000-000000000047', 'Барилгын шоо тоглоом', 'building-blocks-set', 'Хүссэн бүхнээ бүтээх 1,000 өнгө өнгийн холбогддог шоо.', 34.99, null, '11111111-0000-4000-8000-000000000007', array['https://images.unsplash.com/photo-1587654780291-39c9404d746b?w=1000&q=80&auto=format&fit=crop']::text[], 36, 4.7, 88, false, true, now() - interval '92 days'),
  ('22222222-0000-4000-8000-000000000048', 'Ретро тоглоом машин', 'vintage-toy-car', 'Ар тийш нь татаад тавихад явдаг, хаалга нь онгойдог металл кабриолет.', 15.99, null, '11111111-0000-4000-8000-000000000007', array['https://images.unsplash.com/photo-1594787318286-3d835c1d207f?w=1000&q=80&auto=format&fit=crop']::text[], 64, 4.5, 41, false, true, now() - interval '94 days'),
  ('22222222-0000-4000-8000-000000000049', 'Стратегийн ширээний тоглоом', 'strategy-board-game', '2–6 тоглогчтой, 10+ насныханд зориулсан газар нутаг эзлэх тактикийн тоглоом.', 29.99, null, '11111111-0000-4000-8000-000000000007', array['https://images.unsplash.com/photo-1606503153255-59d8b8b82176?w=1000&q=80&auto=format&fit=crop']::text[], 23, 4.6, 57, false, true, now() - interval '96 days'),
  ('22222222-0000-4000-8000-000000000050', 'Модон галт тэрэгний багц', 'wooden-train-set', 'Гүүр, дохио, хотын буудал бүхий 52 хэсэгтэй модон төмөр зам.', 39.99, null, '11111111-0000-4000-8000-000000000007', array['https://images.unsplash.com/photo-1596461404969-9ae70f2830c1?w=1000&q=80&auto=format&fit=crop']::text[], 17, 4.8, 33, false, true, now() - interval '98 days');
